const isBill = body => /bill/i.test(String(body.kind || ''));

// Returns {amount, months, label} or {error}. `owed` is what the book says, for a bill.
function priceOrder(body, owed) {
  const asked = Number(body.amount);
  if (!Number.isFinite(asked) || asked < 1 || asked > 50000) return { error: "That amount doesn't look right." };

  if (isBill(body)) {
    if (!owed || !Number.isFinite(owed.due) || owed.due < 1) return { error: "We couldn't find a bill for that car." };
    const months = owed.fee > 0 ? Math.max(1, Math.floor(owed.due / owed.fee)) : 1;
    return { amount: Math.round(owed.due), months, label: body.label || 'Monthly bill' };
  }
  const p = findProduct(body);
  if (!p) return { error: "We couldn't work out what you're paying for." };
  if (Math.round(asked) !== p.price) return { error: 'That price is out of date. Reload the page and try again.' };
  return { amount: p.price, months: p.months, label: p.name };
}

// Cashfree signs (timestamp + raw body) with the secret key, base64 of HMAC-SHA256.
function verifyWebhook(rawBody, timestamp, signature, secret, nowMs) {
  if (!rawBody || !timestamp || !signature || !secret) return { ok: false, why: 'missing signature' };
  const expected = hmacSha256Base64(secret, timestamp + rawBody);
  if (!sameSecret(expected, signature)) return { ok: false, why: 'bad signature' };
  const tsMs = Number(timestamp) > 1e12 ? Number(timestamp) : Number(timestamp) * 1000;
  const age = (nowMs - tsMs) / 1000;
  if (!Number.isFinite(age) || Math.abs(age) > 300) return { ok: false, why: 'too old' };
  return { ok: true };
}

// n8n hands back Notion dates as {start: "2026-10-29"}, not a string. Reading it as a
// string silently makes every car look unpaid, so always come through here.
function dateText(v) {
  if (!v) return '';
  if (typeof v === 'string') return v.slice(0, 10);
  if (typeof v === 'object' && v.start) return String(v.start).slice(0, 10);
  return '';
}

// A new cycle runs from the later of today and the current paid-up date, never from today
// alone, or a late payer quietly loses the weeks they already paid for.
function advancePaidUpTo(paidUpTo, months, todayISO) {
  const cur = dateText(paidUpTo), from = cur && cur > todayISO ? cur : todayISO;
  const d = new Date(from + 'T00:00:00Z');
  const origDay = d.getUTCDate();
  d.setUTCMonth(d.getUTCMonth() + months);
  // Clamp month-end overflow: Jan 31 + 1 month must be Feb 28, not Mar 3
  if (d.getUTCDate() !== origDay) d.setUTCDate(0);
  return d.toISOString().slice(0, 10);
}

// P1/P5: Price from the car's own Notion row, not from a browser-sent amount.
// Require exact plate match (not last-4 contains).
const body = $('Order maango (webhook)').first().json.body || {};
const reg = String(body.num || '').replace(/[^A-Za-z0-9]/g, '').toUpperCase();
const kind = String(body.kind || '');
const newOrderId = () => 'WD' + Date.now().toString(36).toUpperCase() + Math.random().toString(36).slice(2, 6).toUpperCase();
// P6: return_url is fixed server-side; never from the browser (open-redirect)
const returnUrl = 'https://washingdaddy.com/pay/?order_id={order_id}';
const base = SANDBOX ? 'https://sandbox.cashfree.com' : 'https://api.cashfree.com';
const phone = String(body.phone || '').replace(/\D/g, '').slice(-10);
const customer = () => ({
  customer_id: 'wd_' + phone,
  customer_phone: phone,
  customer_name: String(body.name || '').slice(0, 60) || 'Washing Daddy customer',
});
// One Cashfree order. tags.kind tells the hook what to do with the money:
// 'plan'/'bill' move the paid-up date, 'tip'/'extra' only message Ravi.
const order = (amount, months, note, tags) => {
  const orderId = newOrderId();
  return [{ json: {
    ok: true, orderId, months, expectedAmount: amount, base, discount: 0,
    order: {
      order_id: orderId,
      order_amount: amount,
      order_currency: 'INR',
      customer_details: customer(),
      order_meta: { return_url: returnUrl },
      order_note: String(note).slice(0, 200),
      order_tags: Object.assign({ months: String(months), expectedAmount: String(amount) }, tags),
    },
  } }];
};
const refuse = message => [{ json: { ok: false, message } }];

// Tips bypass the Notion book — amount comes from the browser (₹20–₹500 enforced here).
if (/tip/i.test(kind)) {
  const tipAmt = Number(body.amount);
  if (!Number.isFinite(tipAmt) || tipAmt < 20 || tipAmt > 500) return refuse('Tip must be between ₹20 and ₹500.');
  if (phone.length !== 10) return refuse('Phone number should be 10 digits.');
  return order(tipAmt, 0, body.label || 'Tip', { kind: 'tip' });
}
if (phone.length !== 10) return refuse('Phone number should be 10 digits.');
if (!reg) return refuse('Car registration is required.');

// Store and one-time wash prices. Keep in step with PRODUCTS and book() in the customer app.
const STORE = {
  perfume: ["Car Perfume", 499], micro: ['Microfibre Set', 349], tyre: ['Tyre Shine Gel', 299],
  ceramic: ['Ceramic Quick Coat', 899], mount: ['Vent Mount', 1299], inflator: ['Tyre Inflator', 2499],
  cover: ['Body Cover', 1899], mats: ['7D Floor Mats', 3499], dashcam: ['4K Dash Cam', 5999],
  detail: ['Detailing Session', 2100],
};
const WASHES = {
  // On-demand washes, same list on washingdaddy.com, /pay/ and the customer app.
  wash: ['WD Wash', 199], deep: ['WD Deep Cleaning', 800], exclusive: ['WD Exclusive', 2100],
  // Ids older app builds still send, priced as the nearest current wash.
  interior: ['WD Wash', 199], combo: ['WD Wash', 199], detailing: ['WD Deep Cleaning', 800],
};
const PLAN_PRICE = id => (PRODUCTS.find(p => p.id === id && p.months === 1) || {}).price || 0;
const PLAN_NAME = id => (PRODUCTS.find(p => p.id === id) || {}).name || id;
// Extras never move the paid-up date; the hook only messages Ravi with the note.
const extra = (amount, note) => order(amount, 0, note + ' · ' + reg, { kind: 'extra', reg });

// Store order: the app sends item ids and quantities, we price them.
if (/^order$/i.test(kind)) {
  const items = Array.isArray(body.items) ? body.items : [];
  let total = 0; const lines = [];
  for (const it of items) {
    const s = STORE[String(it && it.id)], q = Math.round(Number(it && it.q));
    if (!s || !(q >= 1 && q <= 10)) return refuse('Something in your cart is no longer sold. Refresh and try again.');
    total += s[1] * q; lines.push(s[0] + (q > 1 ? ' x' + q : ''));
  }
  if (!lines.length) return refuse('Your cart is empty.');
  return extra(total, 'Store: ' + lines.join(', '));
}

// One-time wash, booked from the app.
if (/one-?time|^wash$/i.test(kind)) {
  const w = WASHES[String(body.service || '')];
  if (!w) return refuse("We couldn't work out which wash you picked.");
  return extra(w[1], 'One-time: ' + w[0]);
}

// ---------------------------------------------------------------------------
// Invite (friend gets ₹200 off the first plan) and Referral Credit. Contract of 1 Nov 2026.
// The browser sends only the code (`ref`), never an amount. Who the referrer is, whether the
// payer is new, and how much credit a car has all come from Notion rows. What was applied goes
// into the Cashfree order tags (only this workflow can create orders with our keys) and the
// hook reads it back from the signed webhook.
const INVITE_OFF = 200;
const REF_RX = /^WD\d{6}$/;
const digits = s => String(s == null ? '' : s).replace(/\D/g, '');
const prop = (row, k) => (row && row.properties ? row.properties[k] : undefined);
const rowText = (row, k) => { const v = prop(row, k); return ((v && (v.rich_text || v.title)) || []).map(t => t.plain_text || '').join('').trim(); };
const rowPhone = row => digits((prop(row, 'Phone') || {}).phone_number).slice(-10);
const hasInviteColumns = row => !!prop(row, 'Referred By') && !!prop(row, 'Referral Credit');
// New customer: no payment id, no paid-up date, and nobody has invited them yet.
const neverPaid = row => !rowText(row, 'Last Payment Id') && !dateText((prop(row, 'Service Paid Up To') || {}).date) && !rowText(row, 'Referred By');
const isPlanKind = /^(monthly )?plan$/i.test(kind);          // friend discount: plan payments only
const isPlanOrBill = /plan|bill/i.test(kind) && !/upgrade/i.test(kind); // credit: plan or monthly bill
const refCode = String(typeof body.ref === 'string' ? body.ref : '').trim().toUpperCase();

// -> {off, code, referrerId} or {off: 0, why}
function inviteFor(carRow) {
  if (!isPlanKind || !refCode) return { off: 0, why: 'none' };
  if (!REF_RX.test(refCode)) return { off: 0, why: 'bad code' };
  let res;
  try { res = $('Referrer dhoondo').first().json; } catch (e) { return { off: 0, why: 'no lookup' }; }
  if (!res || res.object === 'error' || res.error || !Array.isArray(res.results)) return { off: 0, why: 'lookup failed' };
  if (res.has_more) return { off: 0, why: 'lookup incomplete' };   // cannot prove "exactly one"
  const six = refCode.slice(2);
  const live = res.results.filter(row => row && !row.archived && !row.in_trash);
  const hits = live.filter(row => rowPhone(row).length >= 6 && rowPhone(row).slice(-6) === six);
  if (hits.length !== 1) return { off: 0, why: hits.length ? 'ambiguous code' : 'unknown code' };
  const referrer = hits[0], refPhone = rowPhone(referrer);
  const carPhone = carRow ? rowPhone(carRow) : '';
  // Own code: same row, same phone (as sent, or as on the car's row), or a phone ending in the code.
  if ((carRow && carRow.id === referrer.id) || refPhone === phone || (carPhone && refPhone === carPhone)
      || phone.slice(-6) === six || (carPhone && carPhone.slice(-6) === six)) return { off: 0, why: 'own code' };
  if (!hasInviteColumns(referrer)) return { off: 0, why: 'columns missing' };
  if (carRow && (!hasInviteColumns(carRow) || !neverPaid(carRow))) return { off: 0, why: 'not first payment' };
  // Any other car on the book under the payer's phone that has paid means this is not a new customer.
  const mine = live.filter(row => { const ph = rowPhone(row); return ph && (ph === phone || (carPhone && ph === carPhone)); });
  if (mine.some(row => !neverPaid(row))) return { off: 0, why: 'not first payment' };
  return { off: INVITE_OFF, code: refCode, referrerId: referrer.id };
}

// Referral Credit on the car's own row; spent only on plan or monthly-bill payments for that row.
function creditFor(carRow) {
  if (!carRow || !isPlanOrBill) return 0;
  const c = Number((prop(carRow, 'Referral Credit') || {}).number);
  return Number.isFinite(c) && c > 0 ? Math.floor(c) : 0;
}

// A plan or bill order with the invite discount and the car's credit taken off.
function planOrder(full, months, note, tags, carRow) {
  const inv = inviteFor(carRow);
  let off = Math.min(inv.off || 0, full);
  let credit = Math.min(creditFor(carRow), full - off);
  // Cashfree cannot take a ₹0 order, and a free order would move the paid-up date with no
  // signed payment behind it, so at least ₹1 is always charged. Credit gives way first.
  let pay = full - off - credit;
  if (pay < 1) { const short = 1 - pay, c = Math.min(credit, short); credit -= c; off -= (short - c); pay = 1; }
  const t = Object.assign({}, tags, { fullAmount: String(full) });
  const bits = [note];
  if (off > 0) { t.invite = inv.code + ':' + inv.referrerId + ':' + off; bits.push('invite ' + inv.code + ' -Rs' + off); }
  if (credit > 0) { t.creditUsed = String(credit); bits.push('credit -Rs' + credit); }
  const out = order(pay, months, bits.join(' · '), t);
  Object.assign(out[0].json, { discount: off + credit, inviteDiscount: off, creditUsed: credit, fullAmount: full, inviteWhy: off > 0 ? 'applied' : (inv.why || 'none') });
  return out;
}
// ---------------------------------------------------------------------------

const found = $('Us gaadi ka bill').first().json || {};
// Exact-plate filter in code (Notion only supports 'contains')
const rows = (found.results || []).filter(r => {
  const num = (r.properties['Car Number']?.rich_text || []).map(t => t.plain_text).join('');
  return num.replace(/[^A-Za-z0-9]/g, '').toUpperCase() === reg;
});
if (rows.length > 1) return refuse('More than one car matched. Please contact us.');
const todayISO = new Date(Date.now() + 5.5 * 3600e3).toISOString().slice(0, 10);

// Mid-month upgrade: the difference between the two monthly prices for the days already paid for.
// For a car on the book the current price and paid-up date come from its row.
if (/^upgrade$/i.test(kind)) {
  const to = PLAN_PRICE(String(body.toPlan || ''));
  if (!to) return refuse("We couldn't work out which plan you picked.");
  let cur, till;
  if (rows.length) {
    cur = rows[0].properties['Monthly Fee']?.number || 0;
    till = dateText(rows[0].properties['Service Paid Up To']?.date);
  } else {
    cur = PLAN_PRICE(String(body.fromPlan || ''));
    till = /^\d{4}-\d{2}-\d{2}$/.test(String(body.till || '')) ? String(body.till) : '';
  }
  if (!cur) return refuse("We couldn't find your current plan. Please contact us.");
  if (to <= cur) return refuse('That plan costs the same or less, so there is nothing to pay today.');
  const left = till > todayISO ? Math.min(31, Math.round((Date.parse(till) - Date.parse(todayISO)) / 864e5)) : 0;
  const amount = Math.round((to - cur) * left / 30);
  if (amount < 1) return refuse('Nothing to pay today. Your new plan starts with your next payment.');
  return extra(amount, 'Upgrade to ' + PLAN_NAME(String(body.toPlan)) + ', ' + left + ' days');
}

// A car that is not on the book yet (signed up in the app) can still pay for a plan at list
// price. The hook finds no row, logs a lead and tells Ravi, who adds the car to the book.
if (!rows.length) {
  if (isBill(body)) return refuse("We couldn't find that car on the book.");
  const priced = priceOrder(body, null);
  if (priced.error) return refuse(priced.error);
  if (priced.months < 1) return refuse("We couldn't work out what you're paying for.");
  return planOrder(priced.amount, priced.months, [priced.label, reg].join(' · '), { kind: 'plan', reg }, null);
}

const r = rows[0], p = r.properties;
const fee = p['Monthly Fee']?.number || 0;
const owes = p['Owes Now']?.number || 0;
if (fee < 1) return refuse("This car doesn't have a payment amount set yet.");

const due = owes > 0 ? owes : fee;
const months = Math.max(1, Math.floor(due / fee));
const expectedAmount = Math.round(due);
// pageId + expectedAmount go into tags so the hook can verify and skip the plate search
return planOrder(expectedAmount, months, ['Monthly bill', reg].join(' · '), { kind: 'bill', reg, pageId: r.id }, r);

// Hand the browser only the session id and what it will be charged. Anything else Cashfree said stays here.
const r = $input.first().json;
const priced = $('Daam tay karo').first().json || {};
if (!r || !r.payment_session_id) {
  const msg = (r && (r.message || r.error_description)) || "Couldn't start the payment. Try again.";
  return [{ json: { ok: false, message: String(msg).slice(0, 200) } }];
}
return [{ json: { ok: true, paymentSessionId: r.payment_session_id, orderId: r.order_id,
  amount: Number(priced.expectedAmount) || 0,
  discount: Number(priced.discount) || 0,
  inviteDiscount: Number(priced.inviteDiscount) || 0,
  creditUsed: Number(priced.creditUsed) || 0 } }];

// ---------------------------------------------------------------------------
// The Cashfree secret key is read from the n8n environment variable CASHFREE_SECRET
// (set it on the n8n container, like TELEGRAM_CHAT_ID). Never paste it into this node:
// workflow exports end up in the repo. It is only used to check that a webhook really
// came from Cashfree. Everything else reads the "Cashfree live" credential.
const CASHFREE_SECRET = String($env.CASHFREE_SECRET || '').trim();
if (!CASHFREE_SECRET) throw new Error('CASHFREE_SECRET env var is not set - refusing to process webhooks');
// Sandbox while testing. Change to false the day you go live, together with
// CF_MODE in pay/index.html and PAY_LIVE in the customer app.
const SANDBOX = false;
// ---------------------------------------------------------------------------
/* Logic used by the Cashfree workflow's Code nodes. Kept here so it can be tested
   outside n8n; the workflow file embeds the same functions. */
// n8n's Code nodes run in a sandbox with require() turned off, so the signature check
// carries its own SHA-256 rather than Node's crypto module.
const K256 = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

// Bytes, not characters: a rupee sign in the body is three bytes and must be hashed as three.
function utf8Bytes(str) {
  const s = String(str), out = [];
  for (let i = 0; i < s.length; i++) {
    let c = s.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff && i + 1 < s.length) {
      const lo = s.charCodeAt(i + 1);
      if (lo >= 0xdc00 && lo <= 0xdfff) { c = 0x10000 + ((c - 0xd800) << 10) + (lo - 0xdc00); i++; }
    }
    if (c < 0x80) out.push(c);
    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return out;
}

function sha256(bytes) {
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const msg = bytes.slice(), bitLen = bytes.length * 8;
  msg.push(0x80);
  while (msg.length % 64 !== 56) msg.push(0);
  // length goes in as 64 bits; the high word stays 0 for anything a webhook could send
  msg.push(0, 0, 0, 0, (bitLen >>> 24) & 0xff, (bitLen >>> 16) & 0xff, (bitLen >>> 8) & 0xff, bitLen & 0xff);

  const w = new Array(64);
  const rotr = (x, n) => ((x >>> n) | (x << (32 - n))) >>> 0;

  for (let i = 0; i < msg.length; i += 64) {
    for (let t = 0; t < 16; t++) {
      w[t] = ((msg[i + t * 4] << 24) | (msg[i + t * 4 + 1] << 16) | (msg[i + t * 4 + 2] << 8) | msg[i + t * 4 + 3]) >>> 0;
    }
    for (let t = 16; t < 64; t++) {
      const s0 = (rotr(w[t - 15], 7) ^ rotr(w[t - 15], 18) ^ (w[t - 15] >>> 3)) >>> 0;
      const s1 = (rotr(w[t - 2], 17) ^ rotr(w[t - 2], 19) ^ (w[t - 2] >>> 10)) >>> 0;
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let t = 0; t < 64; t++) {
      const S1 = (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) >>> 0;
      const ch = ((e & f) ^ (~e & g)) >>> 0;
      const t1 = (h + S1 + ch + K256[t] + w[t]) >>> 0;
      const S0 = (rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) >>> 0;
      const maj = ((a & b) ^ (a & c) ^ (b & c)) >>> 0;
      const t2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0;
      d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0; H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0; H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;
  }
  const out = [];
  for (const v of H) out.push((v >>> 24) & 0xff, (v >>> 16) & 0xff, (v >>> 8) & 0xff, v & 0xff);
  return out;
}

function base64(bytes) {
  const A = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let out = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const n = (bytes[i] << 16) | ((bytes[i + 1] || 0) << 8) | (bytes[i + 2] || 0);
    out += A[(n >> 18) & 63] + A[(n >> 12) & 63];
    out += i + 1 < bytes.length ? A[(n >> 6) & 63] : '=';
    out += i + 2 < bytes.length ? A[n & 63] : '=';
  }
  return out;
}

// The raw body can arrive base64-encoded as binary, and the sandbox has no Buffer,
// so it is decoded here. The signature is over these exact bytes.
function base64ToUtf8(b64) {
  const A = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const s = String(b64).replace(/[^A-Za-z0-9+/]/g, ''), bytes = [];
  for (let i = 0; i < s.length; i += 4) {
    const n = (A.indexOf(s[i]) << 18) | (A.indexOf(s[i + 1]) << 12) |
              ((A.indexOf(s[i + 2]) & 63) << 6) | (A.indexOf(s[i + 3]) & 63);
    bytes.push((n >> 16) & 0xff);
    if (i + 2 < s.length) bytes.push((n >> 8) & 0xff);
    if (i + 3 < s.length) bytes.push(n & 0xff);
  }
  let out = '';
  for (let i = 0; i < bytes.length; i++) {
    const c = bytes[i];
    if (c < 0x80) out += String.fromCharCode(c);
    else if (c < 0xe0) { out += String.fromCharCode(((c & 31) << 6) | (bytes[++i] & 63)); }
    else if (c < 0xf0) { out += String.fromCharCode(((c & 15) << 12) | ((bytes[++i] & 63) << 6) | (bytes[++i] & 63)); }
    else {
      const cp = ((c & 7) << 18) | ((bytes[++i] & 63) << 12) | ((bytes[++i] & 63) << 6) | (bytes[++i] & 63);
      const u = cp - 0x10000;
      out += String.fromCharCode(0xd800 + (u >> 10), 0xdc00 + (u & 1023));
    }
  }
  return out;
}

function hmacSha256Base64(key, message) {
  let k = utf8Bytes(key);
  if (k.length > 64) k = sha256(k);
  while (k.length < 64) k.push(0);
  const inner = [], outer = [];
  for (let i = 0; i < 64; i++) { inner.push(k[i] ^ 0x36); outer.push(k[i] ^ 0x5c); }
  return base64(sha256(outer.concat(sha256(inner.concat(utf8Bytes(message))))));
}

