  if (row) {
    const rp = row.properties || {};
    if (!rp['Referred By']) return no('the Referred By column is missing');
    const rb = (rp['Referred By'].rich_text || []).map(t => t.plain_text).join('').trim();
    if (rb) return no('this car was already referred by ' + rb.slice(0, 20));
    if (seenIds.length || dateText(rp['Service Paid Up To']?.date)) return no('this car had paid before');
  }
  return { inviteCredit: true, referredBy: row ? paid.inviteCode : '', inviteKeys };
}

// P5: exact plate match
const rows = (res.results || []).filter(r => {
  const num = (r.properties['Car Number']?.rich_text || []).map(t => t.plain_text).join('');
  return num.replace(/[^A-Za-z0-9]/g, '').toUpperCase() === paid.reg;
});
const today = new Date(Date.now() + 5.5 * 3600e3).toISOString().slice(0, 10);

if (!rows.length) {
  rememberPay();
  return [{ json: { ...paid, known: false, today, ...inviteCheck(null, []),
    note: 'Paid ' + paid.amount + ' but no car on the book matches ' + paid.reg } }];
}
const r = rows[0], p = r.properties;
const txt = k => (p[k]?.rich_text || p[k]?.title || []).map(t => t.plain_text).join('');

// P4: idempotency — skip if this payment_id was already recorded on this car
// the column holds the last few ids, comma separated
const seen = txt('Last Payment Id').split(',').map(s => s.trim()).filter(Boolean);
if (paid.ref && seen.includes(String(paid.ref))) {
  rememberPay();
  return [{ json: { ...paid, known: true, today, pageId: r.id, duplicate: true,
    note: 'Duplicate event for ' + paid.ref + ' — already processed' } }];
}

const owes = p['Owes Now']?.number || 0;
const till = advancePaidUpTo(p['Service Paid Up To']?.date, paid.months, today);
// Credit the payer spent on this order comes off their row in the same update. If two orders
// spent the same credit, the second finds less than it used: the column stops at 0 and Ravi is told.
let ownCredit = null, creditShort = 0, creditProblem = '';
if (paid.creditUsed > 0) {
  if (!p['Referral Credit']) creditProblem = 'the Referral Credit column is missing';
  else if (paid.pageId && normId(paid.pageId) !== normId(r.id)) creditProblem = 'the order was made for a different Notion row';
  else {
    const have = Math.max(0, Number(p['Referral Credit'].number) || 0);
    creditShort = Math.max(0, paid.creditUsed - have);
    ownCredit = Math.max(0, have - paid.creditUsed);
  }
}
// What the payment settled: the money plus the discounts the server gave on this order.
const settled = paid.amount + (paid.inviteDisc || 0) + (paid.creditUsed || 0);
return [{ json: { ...paid, known: true, today, pageId: r.id, duplicate: false,
  ...inviteCheck(r, seen), ownCredit, creditShort, creditProblem,
  car: txt('Car'), num: txt('Car Number'), phone: p['Phone']?.phone_number || txt('Customer Group'),
  wasPaidTo: dateText(p['Service Paid Up To']?.date),
  till, owesNow: Math.max(0, Math.round(owes - settled)),
  nextDue: till,
  lastPaymentId: seen.concat(paid.ref ? [String(paid.ref)] : []).slice(-5).join(',') } }];

