parameters.jsCode:
// Notion accepted the update: only now remember this payment id (F7), so a failed update
// can still be retried by Cashfree. Bounded to the last 500 ids.
const p = $('Nayi tareekh ginno').first().json;
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.paidIds)) sd.paidIds = [];
const key = String(p.ref || p.orderId || '');
if (key && !sd.paidIds.includes(key)) {
  sd.paidIds.push(key);
  if (sd.paidIds.length > 500) sd.paidIds = sd.paidIds.slice(-500);
}
return [{ json: p }];

// F5: tell Ravi when a webhook is rejected (bad signature, too old, underpaid, bad tag...).
// Rate limited: at most one message per reason per 10 minutes, so a forger cannot flood the chat.
// The message carries the reason only, never the request body or any header.
const sd = $getWorkflowStaticData('global');
if (!sd.lastAlert || typeof sd.lastAlert !== 'object') sd.lastAlert = {};
const j = $input.first().json;
if (j.ack) return [];                                   // refunds, failed payments etc: not an alarm
const k = String(j.why || 'unknown').split(':')[0].slice(0, 40);
const now = Date.now();
if (now - (sd.lastAlert[k] || 0) < 600000) return [];
sd.lastAlert[k] = now;
const keys = Object.keys(sd.lastAlert);
if (keys.length > 50) keys.sort((a, b) => sd.lastAlert[a] - sd.lastAlert[b]).slice(0, keys.length - 50).forEach(x => delete sd.lastAlert[x]);
const hint = /underpaid|currency|expectedAmount|discount/.test(k) ? ' (a payment came in that does not match its order: check Cashfree)'
  : /signature|missing/.test(k) ? ' (possible forged call, or CASHFREE_SECRET does not match)' : '';
return [{ json: { text: '⚠ Cashfree webhook REJECTED: ' + String(j.why || 'unknown').slice(0, 120) + hint } }];

// Invite reward: +₹200 Referral Credit on the referrer's row, read fresh just before writing.
// The referrer is the page id from OUR order tag (checked against the code again here), never
// anything the browser sent. Runs only after the payer's own update was accepted by Notion.
const REWARD = 200;
const p = $('Nayi tareekh ginno').first().json;
const res = $input.first().json || {};
const fail = why => [{ json: { ok: false, why: String(why).slice(0, 160) } }];
if (res.object !== 'page' || res.error) {
  return fail('Notion did not return the referrer row (' + String(res.code || res.message || (res.error && res.error.message) || 'no answer').slice(0, 80) + ')');
}
if (String(res.id || '').replace(/-/g, '').toLowerCase() !== String(p.referrerId || '')) return fail('Notion returned a different row');
if (res.archived || res.in_trash) return fail('the referrer row is archived');
const props = res.properties || {};
if (!props['Referral Credit']) return fail('the Referral Credit column is missing');
const ph = String((props['Phone'] || {}).phone_number || '').replace(/\D/g, '');
if (ph.slice(-6) !== String(p.inviteCode || '').slice(2)) return fail("the referrer's phone no longer matches " + p.inviteCode);
const was = Math.max(0, Number(props['Referral Credit'].number) || 0);
// Remember the car and phone that earned this reward. From here on a failure is reported for
// a hand credit and the webhook is NOT retried, so the reward can never be paid twice.
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.invited)) sd.invited = [];
for (const k of (p.inviteKeys || [])) if (!sd.invited.includes(k)) sd.invited.push(k);
if (sd.invited.length > 1000) sd.invited = sd.invited.slice(-1000);
const txt = k => ((props[k] && (props[k].rich_text || props[k].title)) || []).map(t => t.plain_text).join('');
// Ravi, 1 Nov: the referrer earns the credit only if paid up for this month, checked NOW (at
// payment), from the row just read: Service Paid Up To on or after today (IST). The friend's
// discount stands either way. Not paid up = no credit, a line in Ravi's message, no retry.
const d = (props['Service Paid Up To'] || {}).date;
const paidTo = !d ? '' : typeof d === 'string' ? d.slice(0, 10) : String(d.start || '').slice(0, 10);
const todayIST = new Date(Date.now() + 5.5 * 3600e3).toISOString().slice(0, 10);
if (!paidTo || paidTo < todayIST) {
  return [{ json: { ok: false, skip: true, why: 'referrer not paid up (paid to ' + (paidTo || 'never') + ')', pageId: res.id, was, paidTo, car: txt('Car'), num: txt('Car Number') } }];
}
return [{ json: { ok: true, pageId: res.id, was, credit: was + REWARD, paidTo, car: txt('Car'), num: txt('Car Number') } }];

// Builds Ravi's payment message from the payment data (not from whatever node came before).
const p = $('Nayi tareekh ginno').first().json;
const seen = n => { try { return $(n).first().json || null; } catch (e) { return null; } };
const lead = seen('Anjaan gaadi: lead banao');
const cr = seen('Referrer credit ginno');
const cw = seen('Referrer credit karo');
let text;
if (p.isTip) text = 'Got ₹' + p.amount + ': ' + p.label + (p.phone ? '\nFrom ' + p.phone : '');
else if (p.known) text = 'Paid ₹' + p.amount + ' — ' + p.car + ' ' + p.num + '\nCovered till ' + p.till + ' (was ' + (p.wasPaidTo || 'unpaid') + ')\nStill owed: ₹' + p.owesNow;
else text = (lead && lead.object === 'error' ? '⚠ NOTION LEAD NOT SAVED (' + (lead.code || '?') + ')\n' : '')
  + 'Paid ₹' + p.amount + ' but no car on the book matches ' + p.reg + '. Logged as a lead.';
const more = [];
if (!p.isTip && p.inviteDisc > 0) {
  more.push('Invite ' + p.inviteCode + ': friend got ₹' + p.inviteDisc + ' off (list ₹' + p.fullAmount + ').');
  if (p.inviteCredit) {
    if (cr && cr.ok && cw && cw.object === 'page') more.push('₹200 Referral Credit added to ' + (cr.car || '') + ' ' + (cr.num || '') + ' (now ₹' + cr.credit + ').');
    else if (cr && cr.skip) more.push('No ₹200 credit for the referrer ' + (cr.car || '') + ' ' + (cr.num || '') + ' (code ' + p.inviteCode + '): not paid up for this month (paid to ' + (cr.paidTo || 'never') + '). Credit by hand if you want to.');
    else more.push('⚠ Referrer NOT credited: see the alert above.');
    if (!p.known) more.push('When you add this car to the book, set its Referred By to ' + p.inviteCode + '.');
  } else {
    more.push('⚠ No reward for the referrer: ' + (p.inviteProblem || 'not eligible') + '. Check this payment.');
  }
}
if (!p.isTip && p.creditUsed > 0) {
  if (p.creditProblem) more.push('⚠ Used ₹' + p.creditUsed + ' Referral Credit but ' + p.creditProblem + ': take it off by hand.');
  else more.push('Used ₹' + p.creditUsed + ' Referral Credit (left ₹' + p.ownCredit + ').');
  if (p.creditShort > 0) more.push('⚠ Their credit was ₹' + p.creditShort + ' short (spent on two orders?). Check this payment.');
}
return [{ json: { text: more.length ? text + '\n' + more.join('\n') : text } }];
